script:
import * as THREE from "https://esm.sh/three@0.170.0";

const root = element;
const host = root.querySelector("[data-ring]");
const WORD = (host.dataset.word || "Worldwide").split("");
const CFG = {
  fromDeg: 102, toDeg: -295, introMs: 4500, introEase: [0.2, 0.9, 0.3, 0.986],
  ambientMs: 150000, scrollDegPerPx: 0.12, repulse: 2.5,
  pointerXDeg: 18, pointerDamping: 8,
  wordStaggerMs: 600, letterStaggerMs: 55, slideMs: 650, wipeMs: 300, sweepDeg: 14,
  tiltDeg: 18, radius: 45, letterRatio: 0.35, copies: 3, tracking: -0.08,
  radiusVmin: 37, topVmin: 9.2,
  // particle field
  particles: 140000, pointSize: 0.0174, fluidInfluence: 0.79, splatRadius: 0.5,
  torusTube: 0.14 / 0.34, torusStrength: 0.35, torusFalloff: 0.34,
  vignetteAmount: 0.5, vignetteRadius: 0.895, vignetteSoftness: 0.441,
  particleRevealMs: 2400,
};
const G = Math.PI / 180;

function bezier(x1, y1, x2, y2) {
  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
  const cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  const sx = t => ((ax * t + bx) * t + cx) * t, sy = t => ((ay * t + by) * t + cy) * t;
  const dx = t => (3 * ax * t + 2 * bx) * t + cx;
  return x => {
    if (x <= 0) return 0; if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 8; i++) { const e = sx(t) - x; if (Math.abs(e) < 1e-6) break; const d = dx(t); if (Math.abs(d) < 1e-6) break; t -= e / d; }
    return sy(t);
  };
}
const introEase = bezier(...CFG.introEase);
const easeOut = bezier(0, 0, 0.58, 1);

const style = getComputedStyle(root);
const token = (name, fallback) => style.getPropertyValue(name).trim() || fallback;
const letterColor = new THREE.Color(style.color || token("--primary-foreground", "#fafafa"));
const dimColor = new THREE.Color(token("--muted-foreground", "#737373"));
const midColor = new THREE.Color(token("--ring", "#a1a1a1"));
const fontFamily = style.fontFamily || "system-ui, sans-serif";
const reduced = matchMedia("(prefers-reduced-motion: reduce)");

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setClearColor(0x000000, 0);
renderer.autoClear = false;
Object.assign(renderer.domElement.style, { position: "absolute", inset: "0", width: "100%", height: "100%", display: "block" });
host.appendChild(renderer.domElement);

const pointer = { ndc: new THREE.Vector2(9, 9), vel: new THREE.Vector2(), last: null, active: false, tiltX: 0 };

/* ---------- particle field: a rolling hill of points behind the ring ---------- */
const pScene = new THREE.Scene();
const pCam = new THREE.PerspectiveCamera(50, 1, 0.05, 60);
pCam.position.set(0, 0.35, 4);
pCam.lookAt(0, 0, 0);
const P_VIEW_H = 2 * pCam.position.length() * Math.tan(25 * G);

function hill(x, z) {
  return -1.35
    + 1.15 * Math.exp(-((x + 0.9) ** 2) / 7 - ((z + 3.6) ** 2) / 9)
    + 0.75 * Math.exp(-((x - 2.8) ** 2) / 4.5 - ((z + 6.2) ** 2) / 7)
    + 0.55 * Math.exp(-((x + 4.2) ** 2) / 5 - ((z + 7.5) ** 2) / 10)
    + 0.06 * Math.sin(x * 2.1 + z * 1.3) + 0.04 * Math.sin(x * 4.7 - z * 3.1);
}
const N = CFG.particles;
const pos = new Float32Array(N * 3), rnd = new Float32Array(N * 3);
for (let i = 0; i < N; i++) {
  let x, y, z;
  if (i < N * 0.92) {
    x = (Math.random() * 2 - 1) * 7.5;
    z = 2.6 - Math.pow(Math.random(), 0.75) * 15;
    y = hill(x, z) + Math.pow(Math.random(), 3) * 0.22;
  } else {
    x = (Math.random() * 2 - 1) * 6.5;
    z = 2 - Math.random() * 12;
    y = -1.2 + Math.random() * 4.2;
  }
  pos.set([x, y, z], i * 3);
  rnd.set([Math.random(), Math.random(), Math.random()], i * 3);
}
const pGeo = new THREE.BufferGeometry();
pGeo.setAttribute("position", new THREE.BufferAttribute(pos, 3));
pGeo.setAttribute("aRandom", new THREE.BufferAttribute(rnd, 3));

const torus = new THREE.Object3D();
torus.rotation.x = CFG.tiltDeg * G;
const pUniforms = {
  uTime: { value: 0 }, uPointSize: { value: CFG.pointSize }, uProj: { value: 1 }, uPixelRatio: { value: renderer.getPixelRatio() },
  uPointer: { value: pointer.ndc }, uVel: { value: pointer.vel }, uInfluence: { value: CFG.fluidInfluence }, uSplat: { value: CFG.splatRadius },
  uAspect: { value: 1 }, uReveal: { value: 0 }, uMotion: { value: 1 },
  uTorusInv: { value: new THREE.Matrix4() }, uTorusRot: { value: new THREE.Matrix3() },
  uTorusR: { value: 1.4 }, uTorusTube: { value: 0.58 }, uTorusStrength: { value: CFG.torusStrength },
  uVig: { value: new THREE.Vector3(CFG.vignetteAmount, CFG.vignetteRadius, CFG.vignetteSoftness) },
  uColDim: { value: dimColor }, uColMid: { value: midColor }, uColHi: { value: letterColor },
};
const pMat = new THREE.ShaderMaterial({
  uniforms: pUniforms, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
  vertexShader: `
attribute vec3 aRandom;
uniform float uTime, uPointSize, uProj, uPixelRatio, uInfluence, uSplat, uAspect, uReveal, uMotion;
uniform vec2 uPointer, uVel;
uniform mat4 uTorusInv; uniform mat3 uTorusRot;
uniform float uTorusR, uTorusTube, uTorusStrength;
uniform vec3 uVig;
varying float vAlpha; varying float vShade;
void main() {
  vec3 p = position;
  float t = uTime * uMotion;
  p.x += sin(t * 0.2 + aRandom.x * 6.2831 + p.z * 0.4) * 0.025;
  p.y += sin(t * 0.27 + aRandom.y * 6.2831 + p.x * 0.5) * 0.018;
  p.z += cos(t * 0.17 + aRandom.z * 6.2831 + p.y * 0.6) * 0.02;

  // the ring's torus pushes points out of its tube
  vec3 q = (uTorusInv * vec4(p, 1.0)).xyz;
  vec2 xz = q.xz; float rl = max(length(xz), 1e-4);
  vec3 core = vec3(xz / rl * uTorusR, 0.0).xzy;
  core = vec3(xz.x / rl * uTorusR, 0.0, xz.y / rl * uTorusR);
  vec3 away = q - core; float al = max(length(away), 1e-4);
  float dist = al - uTorusTube;
  float falloff = uTorusTube;
  float band = clamp(dist / falloff, 0.0, 1.0);
  float fade = 1.0 - band * band * band * (band * (band * 6.0 - 15.0) + 10.0);
  float interior = clamp(-dist / falloff, 0.0, 1.0);
  float repel = uTorusStrength * (fade + interior) * falloff;
  p += uTorusRot * (away / al) * repel;

  vec4 mv = modelViewMatrix * vec4(p, 1.0);
  vec4 clip = projectionMatrix * mv;
  vec2 ndc = clip.xy / clip.w;
  vec2 d = ndc - uPointer; d.x *= uAspect;
  float f = exp(-dot(d, d) / (uSplat * uSplat * 0.5));
  clip.xy += uVel * uInfluence * f * clip.w * mix(0.6, 1.4, aRandom.x);
  gl_Position = clip;

  float depth = -mv.z;
  float px = uPointSize * uProj / depth * uPixelRatio;
  gl_PointSize = clamp(px, 1.0, 4.0 * uPixelRatio) * mix(0.7, 1.3, aRandom.z);

  vec2 sc = clip.xy / clip.w;
  float vr = length(sc) / 1.4142;
  float vig = 1.0 - uVig.x * smoothstep(uVig.y - uVig.z, uVig.y, vr);
  float rr = length(sc * vec2(uAspect, 1.0)) / length(vec2(uAspect, 1.0));
  float reveal = smoothstep(uReveal, uReveal - 0.18, rr);
  float fog = smoothstep(15.0, 3.0, depth);
  vShade = clamp((p.y + 1.4) / 1.6, 0.0, 1.0) * 0.6 + aRandom.y * 0.4;
  vAlpha = 0.5 * vig * reveal * fog * mix(0.45, 1.15, pow(aRandom.y, 0.65));
}`,
  fragmentShader: `
uniform vec3 uColDim, uColMid, uColHi;
varying float vAlpha; varying float vShade;
void main() {
  float d = length(gl_PointCoord - 0.5);
  float a = smoothstep(0.5, 0.0, d);
  vec3 c = vShade < 0.5 ? mix(uColDim, uColMid, vShade * 2.0) : mix(uColMid, uColHi, vShade * 2.0 - 1.0);
  gl_FragColor = vec4(c, a * vAlpha);
}`,
});
const points = new THREE.Points(pGeo, pMat);
points.frustumCulled = false;
pScene.add(points);

/* ---------- letter ring ---------- */
const scene = new THREE.Scene();
const DIST = CFG.radius * 13.5;
const camera = new THREE.PerspectiveCamera(12, 1, 1, DIST * 4);
camera.position.set(0, 0, DIST);
const tilt = new THREE.Group();
const spin = new THREE.Group();
tilt.rotation.x = CFG.tiltDeg * G;
tilt.add(spin);
scene.add(tilt);

const FONT_PX = 256;
const em = CFG.radius * CFG.letterRatio;
const glyphs = new Map();
function glyph(ch) {
  if (glyphs.has(ch)) return glyphs.get(ch);
  const c = document.createElement("canvas");
  const ctx = c.getContext("2d");
  const font = `500 ${FONT_PX}px ${fontFamily}`;
  ctx.font = font;
  const m = ctx.measureText(ch);
  const asc = m.fontBoundingBoxAscent ?? FONT_PX * 0.98, desc = m.fontBoundingBoxDescent ?? FONT_PX * 0.26;
  const pad = 24;
  c.width = Math.ceil(m.width + pad * 2); c.height = Math.ceil(asc + desc + pad * 2);
  ctx.font = font; ctx.fillStyle = "#fff"; ctx.textBaseline = "alphabetic";
  ctx.fillText(ch, pad, pad + asc);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace; tex.anisotropy = 4;
  const g = { tex, advance: m.width / FONT_PX, w: c.width / FONT_PX * em, h: c.height / FONT_PX * em };
  glyphs.set(ch, g);
  return g;
}

const shared = {
  uPointer: { value: pointer.ndc }, uVel: { value: pointer.vel },
  uInfluence: { value: CFG.repulse }, uAspect: { value: 1 },
};
const vert = `
uniform vec2 uPointer; uniform vec2 uVel; uniform float uInfluence; uniform float uAspect;
varying vec2 vUv;
void main() {
  vUv = uv;
  vec4 clip = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  vec2 d = clip.xy / clip.w - uPointer; d.x *= uAspect;
  float f = exp(-dot(d, d) / 0.05);
  clip.xy += uVel * uInfluence * 0.5 * f * clip.w;
  gl_Position = clip;
}`;
const frag = `
uniform sampler2D map; uniform vec3 uColor; uniform float uReveal; uniform float uOpacity;
varying vec2 vUv;
void main() {
  if (vUv.x > uReveal) discard;
  float a = texture2D(map, vUv).a * uOpacity;
  if (a < 0.003) discard;
  gl_FragColor = vec4(uColor, a);
}`;

const letters = [];
const all = [];
for (let w = 0; w < CFG.copies; w++) WORD.forEach((ch, i) => all.push({ ch, wordIndex: w, letterIndex: i }));
const widthsDeg = all.map(({ ch }) => (glyph(ch).advance + CFG.tracking) * CFG.letterRatio * (180 / Math.PI));
const gap = (360 - widthsDeg.reduce((a, b) => a + b, 0)) / CFG.copies;
let cursor = gap / 2, k = 0;
for (let w = 0; w < CFG.copies; w++) {
  for (let i = 0; i < WORD.length; i++, k++) {
    const g = glyph(all[k].ch);
    const rest = cursor + widthsDeg[k] / 2;
    cursor += widthsDeg[k];
    const mat = new THREE.ShaderMaterial({
      vertexShader: vert, fragmentShader: frag, transparent: true, depthWrite: false, side: THREE.DoubleSide,
      uniforms: { ...shared, map: { value: g.tex }, uColor: { value: letterColor }, uReveal: { value: 0 }, uOpacity: { value: 1 } },
    });
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(g.w, g.h, 12, 12), mat);
    mesh.position.z = CFG.radius;
    const holder = new THREE.Group();
    holder.add(mesh);
    holder.rotation.y = (rest - CFG.sweepDeg) * G;
    spin.add(holder);
    letters.push({ holder, mat, rest, ...all[k] });
  }
  cursor += gap;
}

let W = 1, H = 1;
function resize() {
  const r = host.getBoundingClientRect();
  W = Math.max(1, r.width); H = Math.max(1, r.height);
  renderer.setSize(W, H, false);
  const vmin = Math.min(W, H) / 100;
  const centerPx = (CFG.topVmin + CFG.radiusVmin) * vmin;

  camera.aspect = W / H;
  const viewH = (2 * CFG.radius) * H / (2 * CFG.radiusVmin * vmin);
  camera.fov = 2 * Math.atan(viewH / 2 / DIST) / G;
  camera.updateProjectionMatrix();
  tilt.position.y = (H / 2 - centerPx) * viewH / H;
  shared.uAspect.value = W / H;

  pCam.aspect = W / H;
  pCam.updateProjectionMatrix();
  const ringR = CFG.radiusVmin * vmin / H * P_VIEW_H;
  pUniforms.uTorusR.value = ringR;
  pUniforms.uTorusTube.value = ringR * CFG.torusTube;
  torus.position.y = (H / 2 - centerPx) / H * P_VIEW_H;
  torus.updateMatrixWorld(true);
  pUniforms.uTorusInv.value.copy(torus.matrixWorld).invert();
  pUniforms.uTorusRot.value.setFromMatrix4(torus.matrixWorld);
  pUniforms.uProj.value = H / (2 * Math.tan(pCam.fov * G / 2));
  pUniforms.uAspect.value = W / H;
  pUniforms.uPixelRatio.value = renderer.getPixelRatio();
}
new ResizeObserver(resize).observe(host);
resize();

let scrollSpin = 0;
root.addEventListener("wheel", e => { scrollSpin -= Math.max(-180, Math.min(180, e.deltaY)) * CFG.scrollDegPerPx; }, { passive: true });
let lastScrollY = window.scrollY;
addEventListener("scroll", () => { const y = window.scrollY; scrollSpin -= Math.max(-180, Math.min(180, y - lastScrollY)) * CFG.scrollDegPerPx; lastScrollY = y; }, { passive: true });

function onMove(e) {
  const r = host.getBoundingClientRect();
  const x = ((e.clientX - r.left) / r.width) * 2 - 1, y = -(((e.clientY - r.top) / r.height) * 2 - 1);
  if (pointer.last) pointer.vel.set(pointer.vel.x + (x - pointer.last.x), pointer.vel.y + (y - pointer.last.y));
  pointer.last = { x, y };
  pointer.ndc.set(x, y);
  pointer.active = true;
}
root.addEventListener("pointermove", onMove);
root.addEventListener("pointerleave", () => { pointer.active = false; pointer.last = null; });

let visible = true;
new IntersectionObserver(([en]) => { visible = en.isIntersecting; }, { threshold: 0 }).observe(host);

const clock = new THREE.Clock();
let start = null;
function ringAngle(t) {
  if (t <= 0) return CFG.fromDeg;
  if (t < CFG.introMs) return CFG.fromDeg + (CFG.toDeg - CFG.fromDeg) * introEase(t / CFG.introMs);
  return CFG.toDeg - 360 * ((t - CFG.introMs) / CFG.ambientMs);
}

function frame() {
  requestAnimationFrame(frame);
  const dt = Math.min(clock.getDelta(), 0.1);
  if (!visible) return;
  const now = performance.now();
  if (start === null) start = now;
  const t = now - start;
  const calm = reduced.matches;

  const target = pointer.active && !calm ? pointer.ndc.x * CFG.pointerXDeg : 0;
  pointer.tiltX += (target - pointer.tiltX) * (1 - Math.exp(-CFG.pointerDamping * dt));
  pointer.vel.multiplyScalar(Math.exp(-6 * dt));
  shared.uInfluence.value = calm ? 0 : CFG.repulse;

  pUniforms.uTime.value = t / 1000;
  pUniforms.uMotion.value = calm ? 0 : 1;
  pUniforms.uInfluence.value = calm ? 0 : CFG.fluidInfluence;
  pUniforms.uReveal.value = calm ? 1.2 : 1.2 * easeOut(Math.min(t / CFG.particleRevealMs, 1));

  if (calm) {
    const fade = easeOut(Math.min(t / 600, 1));
    spin.rotation.y = (CFG.toDeg + scrollSpin * 0.1) * G;
    for (const l of letters) { l.mat.uniforms.uOpacity.value = fade; l.mat.uniforms.uReveal.value = 1; l.holder.rotation.y = l.rest * G; }
  } else {
    spin.rotation.y = (ringAngle(t) + scrollSpin + pointer.tiltX) * G;
    for (const l of letters) {
      const wStart = l.wordIndex * CFG.wordStaggerMs;
      const d = t - wStart;
      const slide = d <= 0 ? -CFG.sweepDeg : d < CFG.slideMs ? -CFG.sweepDeg * (1 - easeOut(d / CFG.slideMs)) : 0;
      l.holder.rotation.y = (l.rest + slide) * G;
      const p = t - (wStart + l.letterIndex * CFG.letterStaggerMs);
      l.mat.uniforms.uOpacity.value = 1;
      l.mat.uniforms.uReveal.value = p <= 0 ? 0 : p < CFG.wipeMs ? easeOut(p / CFG.wipeMs) : 1;
    }
  }
  renderer.clear();
  renderer.render(pScene, pCam);
  renderer.clearDepth();
  renderer.render(scene, camera);
}
requestAnimationFrame(frame);
